// Inventario (dal vault, pubblicato dai PC) x punteggi (da AA).
const note = $('Read host inventory').first().json;
// Il nodo MCP incarta la risposta: { content: [ { type: 'text', text: <nota> } ] },
// e `text` arriva GIA' come oggetto, non come stringa JSON. Senza sbucciare,
// String(note.content) diventa '[object Object]' e nessun blocco host viene
// trovato -- che e' esattamente come questo bug si e' manifestato.
const rawNote = (note.content && note.content[0] && note.content[0].text) || note;
const payload = typeof rawNote === 'string' ? JSON.parse(rawNote) : rawNote;
const body = String(payload.full_content || payload.content || '');
if (!body.trim()) throw new Error('Nota inventario vuota o illeggibile');
const aa = $input.first().json;
const models = Array.isArray(aa.data) ? aa.data : [];
if (models.length < 50) throw new Error('Catalogo AA sospetto: ' + models.length + ' modelli');

const hosts = {};
const blockRe = /<!-- model-inventory:([^:]+):start -->([\s\S]*?)<!-- model-inventory:\1:end -->/g;
let bm;
while ((bm = blockRe.exec(body))) {
  const chans = {};
  const lineRe = /^-\s+\*\*([a-z]+)\*\*[^:]*:\s*(.+)$/gm;
  let lm;
  while ((lm = lineRe.exec(bm[2]))) {
    const list = [...lm[2].matchAll(/`([^`]+)`/g)].map(x => x[1]);
    if (list.length) chans[lm[1]] = list;
  }
  hosts[bm[1]] = chans;
}
if (!Object.keys(hosts).length) throw new Error('Nessun blocco host nella nota');

// AA usa un vocabolario di suffissi ricco: va spogliato prima del confronto.
const EFFORT = /\s+\((?:adaptive\s+)?(?:non-)?reasoning(?:,\s*[a-z]+\s+effort)?(?:,\s*[^)]*fallback)?\)$/i;
const LEVEL = /\s+\((?:max|xhigh|high|medium|low|minimal|with fallback|preview)\)$/i;
const DATED = /\s+\((?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\s*'?\d{2}\)$/i;
const BARE = /\s+Preview$/i;
function canonical(v) {
  let o = String(v || '').trim();
  for (let i = 0; i < 4; i += 1) {
    const b = o;
    o = o.replace(EFFORT, '').replace(LEVEL, '').replace(DATED, '').replace(BARE, '').trim();
    if (o === b) break;
  }
  return o;
}
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const index = new Map();
for (const m of models) {
  const sc = m.evaluations && m.evaluations.artificial_analysis_intelligence_index;
  if (!Number.isFinite(sc)) continue;
  const k = norm(canonical(m.name));
  const p = index.get(k);
  if (!p || p.evaluations.artificial_analysis_intelligence_index < sc) index.set(k, m);
}
// Un tag build a 4 cifre in coda ('DeepSeek V4 Flash 0731') e' la stessa
// famiglia dello slug generico che il CLI espone: il vendor serve la build
// corrente. Si fondono SOLO se la variante base esiste davvero, altrimenti
// 'R1 1776' -- dove 1776 e' parte del nome, non una data -- verrebbe rinominato.
for (const [k, m] of [...index]) {
  const base = norm(canonical(m.name).replace(/\s+\d{4}$/, ''));
  if (base === k || !index.has(base)) continue;
  const cur = index.get(base);
  if (cur.evaluations.artificial_analysis_intelligence_index < m.evaluations.artificial_analysis_intelligence_index) index.set(base, m);
}
const SLUG = /-(high|medium|low|max|xhigh|minimal|thinking|reasoning|free|code|mini)$/;
function lookup(slug) {
  let b = String(slug).split('/').pop().trim();
  for (let i = 0; i < 4; i += 1) {
    const hit = index.get(norm(b));
    if (hit) return hit;
    const s = b.replace(SLUG, '');
    if (s === b) break;
    b = s;
  }
  return null;
}

const inv = new Map(); const unmatched = [];
for (const [host, chans] of Object.entries(hosts)) {
  for (const [cli, slugs] of Object.entries(chans)) {
    for (const slug of slugs) {
      if (cli === 'local') {
        // I locali non stanno in AA: il loro valore non e' la classifica.
        const k = 'local|' + slug;
        if (!inv.has(k)) inv.set(k, { name: slug, cli: 'local', exposed: slug, host, idx: null, price: 0, tps: null, ev: {} });
        continue;
      }
      const hit = lookup(slug);
      if (!hit) { unmatched.push(cli + '/' + slug); continue; }
      const c = canonical(hit.name); const k = cli + '|' + c;
      if (inv.has(k)) continue;
      const pr = hit.pricing || {};
      inv.set(k, { name: c, cli, exposed: slug, host, idx: hit.evaluations.artificial_analysis_intelligence_index, price: pr.price_1m_blended_3_to_1, tps: hit.median_output_tokens_per_second, ev: hit.evaluations });
    }
  }
}

// Pavimento: un MODELLO di riferimento, non una soglia scelta a mano. Si alza
// da se' quando il canale aggiorna la build.
const ref = [...inv.values()].find(m => /^DeepSeek V4 Flash/i.test(m.name));
const FLOOR = ref && Number.isFinite(ref.idx) ? ref.idx : 40;
const cloud = [...inv.values()].filter(m => m.cli !== 'local' && Number.isFinite(m.idx));
const catalog = cloud.filter(m => m.idx >= FLOOR).sort((a, b) => b.idx - a.idx);
const cut = cloud.filter(m => m.idx < FLOOR).sort((a, b) => b.idx - a.idx);
const locals = [...inv.values()].filter(m => m.cli === 'local');

function fnv(s) { let h = 2166136261; for (let i = 0; i < s.length; i += 1) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16); }
const fingerprint = fnv(catalog.map(m => m.cli + ':' + m.name + ':' + m.idx + ':' + m.price).sort().join('|') + '#' + locals.map(m => m.name).sort().join('|'));

return [{ json: { catalog, locals, cut, floor: FLOOR, floor_model: ref ? ref.name : '(assente)', hosts: Object.keys(hosts), aa_total: models.length, unmatched, fingerprint } }];

// Ogni ruolo ha i SUOI test e la SUA politica di costo.
// Il perche' di ognuno: 03-INFRA/model-routing-roles.md
const inp = $input.first().json;
const catalog = inp.catalog || []; const locals = inp.locals || [];
const P = { Q: 'quality-first', R: 'ratio', C: 'cheap-first' };
const ROLES = [
  { id: 'L-Arch', data: 'none', profile: P.Q, tests: { lcr: 0.5, hle: 0.3, gpqa: 0.2 }, purpose: 'Architettura, requisiti, design multi-sistema, documenti lunghi' },
  { id: 'L-Debug', data: 'none', profile: P.Q, tests: { terminalbench_v2_1: 0.35, hle: 0.35, lcr: 0.3 }, purpose: 'Diagnosi: bug difficili, tracce, comportamenti che non tornano' },
  { id: 'L-Sys', data: 'infra', profile: P.Q, tests: { terminalbench_v2_1: 0.8, terminalbench_hard: 0.2 }, purpose: 'Infrastruttura, Docker, SSH, incidenti' },
  { id: 'L-Code', data: 'none', profile: P.R, tests: { artificial_analysis_coding_index: 0.7, terminalbench_v2_1: 0.3 }, purpose: 'Patch quotidiane, shell, debug medio' },
  { id: 'L-Build', data: 'none', profile: P.R, tests: { tau_banking: 0.45, tau2: 0.35, terminalbench_v2_1: 0.2 }, purpose: 'n8n complesso, tool chaining, refactor multi-file' },
  { id: 'Frontend', data: 'none', profile: P.R, tests: { artificial_analysis_coding_index: 1 }, purpose: 'Componenti UI, CSS' },
  { id: 'L-Write', data: 'none', profile: P.R, tests: { ifbench: 1 }, purpose: 'Prosa: note, contenuti, candidature, documentazione' },
  { id: 'L-Bulk', data: 'none', profile: P.C, tests: { ifbench: 1 }, purpose: 'Estrazioni, triage, scan, trasformazioni ripetitive' },
  { id: 'Privacy', data: 'personal', profile: P.Q, tests: { artificial_analysis_intelligence_index: 1 }, purpose: 'NDA, dati personali, lavoro che non deve uscire dalla macchina' },
];
// Priori d'uso dove nessun benchmark e' pertinente. L-Write vuoto di proposito:
// quale modello scriva un buon italiano e' esperienza d'uso, non un numero.
const PRIOR = { Frontend: [[/GLM/i, 50], [/Terra/i, 36], [/Opus/i, 30]], 'L-Write': [] };
// INDEX_MAX deve stare SOPRA il massimo del catalogo, o i migliori collassano
// sullo stesso valore e vince quello che costa più'.
const INDEX_MAX = 80; const SPEED_MAX = 250; const W_SPEED = 0.1;
const INTERACTIVE = new Set(['L-Code', 'L-Build', 'L-Sys', 'Frontend', 'L-Bulk', 'L-Write']);
// Scala ASSOLUTA: il min-max relativo schiaccia il più' debole a zero e fa
// eleggere al profilo rapporto il modello più' caro.
function abs(f, raw) {
  if (!Number.isFinite(raw)) return null;
  const pct = f.endsWith('_index') ? (raw / INDEX_MAX) * 100 : raw * 100;
  return Math.max(0, Math.min(100, pct));
}
function median(vals) {
  const v = vals.filter(Number.isFinite).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
}
// Un termine assente vale la MEDIANA: scartarlo e ripesare premia chi non ha
// la misura, quando il valore presente e' sotto la media.
function blend(parts) {
  let s = 0, w = 0;
  for (const [v, weight, fb] of parts) {
    const x = Number.isFinite(v) ? v : (Number.isFinite(fb) ? fb : null);
    if (x === null) continue;
    s += x * weight; w += weight;
  }
  return w > 0 ? s / w : 0;
}
function prior(id, m) { for (const [re, val] of PRIOR[id] || []) if (re.test(m.name)) return val; return 0; }
function roleScore(role, m) {
  let s = 0, w = 0; const missing = [];
  for (const [f, weight] of Object.entries(role.tests)) {
    const v = abs(f, m.ev ? m.ev[f] : null);
    if (v === null) { missing.push(f); continue; }
    s += v * weight; w += weight;
  }
  if (w === 0) return { value: prior(role.id, m), missing };
  return { value: s / w, missing };
}
function speed(role, m) {
  if (!INTERACTIVE.has(role.id)) return null;
  const t = Number(m.tps);
  return Number.isFinite(t) && t > 0 ? Math.min(100, (t / SPEED_MAX) * 100) : null;
}
const out = [];
for (const role of ROLES) {
  // Dati personali: SOLO locale, nessun ripiego cloud.
  const cands = role.data === 'personal' ? locals : catalog;
  if (!cands.length) {
    out.push({ role, eligible: 0, picks: [], pools: [], unassigned: role.data === 'personal' ? 'nessun modello locale sugli host che hanno pubblicato: il ruolo resta non assegnato invece di ricadere su un cloud' : 'nessun candidato' });
    continue;
  }
  const spMed = median(cands.map(m => speed(role, m)));
  const scored = cands.map(m => {
    const rs = roleScore(role, m);
    const q = abs('artificial_analysis_intelligence_index', m.idx);
    const sp = speed(role, m);
    let total, why;
    if (role.profile === P.Q) {
      total = blend([[q, 0.45], [rs.value, 0.45], [sp, W_SPEED, spMed]]);
      why = 'qualita ' + (q === null ? 'n/d' : q.toFixed(0)) + ' + ruolo ' + rs.value.toFixed(0) + ', costo escluso';
    } else if (role.profile === P.R) {
      const merit = blend([[q, 0.45], [rs.value, 0.45], [sp, W_SPEED, spMed]]);
      const p = Math.max(Number.isFinite(m.price) ? m.price : 99, 0.05);
      total = merit / Math.log10(1 + p * 20);
      why = 'merito ' + merit.toFixed(0) + ' / $' + p + ' = ' + total.toFixed(1) + ' per dollaro';
    } else {
      total = blend([[rs.value, 0.9], [sp, W_SPEED, spMed]]);
      why = 'costo $' + m.price + ' (chiave 1), qualita ' + total.toFixed(0) + ' (chiave 2)';
    }
    return { m, rs, total, why };
  });
  if (role.profile === P.C) {
    // Prima il prezzo, POI la qualita': due chiavi in ordine, non una media.
    scored.sort((a, b) => {
      const pa = Number.isFinite(a.m.price) ? a.m.price : 99;
      const pb = Number.isFinite(b.m.price) ? b.m.price : 99;
      return pa !== pb ? pa - pb : b.total - a.total;
    });
  } else {
    scored.sort((a, b) => b.total - a.total);
  }
  // Fallback su POOL DI QUOTA distinti: a quota esaurita un pool sparisce
  // tutto insieme, quindi tre modelli sullo stesso canale sono un modello.
  const picks = [];
  for (const s of scored) {
    if (!picks.length) { picks.push(s); continue; }
    if (picks.length < 3 && !picks.some(p => p.m.cli === s.m.cli)) picks.push(s);
    if (picks.length === 3) break;
  }
  for (const s of scored) { if (picks.length === 3) break; if (!picks.includes(s)) picks.push(s); }
  const pools = [...new Set(picks.map(p => p.m.cli))];
  out.push({ role, eligible: cands.length, pools, pool_warning: pools.length < 3 ? 'solo ' + pools.length + ' pool distinti' : null,
    picks: picks.map((p, i) => ({ slot: ['primario', 'fallback 1', 'fallback 2'][i], name: p.m.name, cli: p.m.cli, exposed: p.m.exposed, price: p.m.price, idx: p.m.idx, tps: p.m.tps, score: Number(p.total.toFixed(2)), why: p.why, missing: p.rs.missing })) });
}
return [{ json: Object.assign({}, inp, { routing: out }) }];

const d = $input.first().json;
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
const L = [];
L.push('<!-- model-routing-governor:start -->');
L.push('## Stato automatico');
L.push('');
L.push('<!-- model-routing-governor:input=' + d.fingerprint + ' -->');
L.push('');
L.push('Punteggi: **Artificial Analysis Data API v2**. Disponibilita: la nota');
L.push('[[03-INFRA/council-model-inventory]], che ogni macchina pubblica da se, perche');
L.push('il workflow gira sulla VPS e i PC sono endpoint spenti.');
L.push('');
L.push('Rigenerato il ' + stamp + '. ' + d.aa_total + ' modelli nel catalogo AA, ' + d.catalog.length + ' invocabili sopra il pavimento, ' + d.cut.length + ' tagliati, ' + d.locals.length + ' locali.');
L.push('Host che hanno pubblicato: ' + d.hosts.map(h => '`' + h + '`').join(', ') + '.');
L.push('');
L.push('Pavimento: **' + d.floor_model + '** (indice ' + d.floor + '). Un modello di riferimento,');
L.push('non una soglia scelta a mano: costa quasi nulla, quindi accettare qualcosa di');
L.push('peggiore per risparmiare su una cifra già nulla non ha senso.');
if (d.unmatched && d.unmatched.length) {
  L.push('');
  L.push('Esposti dai CLI ma assenti da AA, quindi non valutabili: ' + d.unmatched.map(u => '`' + u + '`').join(', ') + '.');
}
L.push('');
L.push('### Catalogo disponibile');
L.push('');
L.push('| Modello | CLI | $ blended 3:1 | AA index | tok/s |');
L.push('|---|---|---:|---:|---:|');
for (const m of d.catalog) L.push('| ' + m.name + ' | ' + m.cli + ' | $' + m.price + ' | ' + m.idx + ' | ' + (Math.round(m.tps || 0) || '--') + ' |');
if (d.locals.length) {
  L.push('');
  L.push('Locali, fuori classifica perche il loro valore non e la capacita ma che il');
  L.push('dato non esce: ' + d.locals.map(m => '`' + m.name + '` su `' + m.host + '`').join(', ') + '.');
}
L.push('');
L.push('### Proposta di routing per ruolo');
L.push('');
L.push('Proposta, non assegnazione: il seat resta una scelta umana. Il perche di ogni');
L.push('ruolo e come scegliere il proprio in [[03-INFRA/model-routing-roles]].');
L.push('');
for (const r of d.routing) {
  L.push('#### ' + r.role.id + ' - ' + r.role.profile);
  L.push('');
  L.push(r.role.purpose + '.');
  L.push('');
  if (r.unassigned) { L.push('> **Non assegnato.** ' + r.unassigned); L.push(''); continue; }
  L.push('| Slot | Modello | CLI | $ | Motivo |');
  L.push('|---|---|---|---:|---|');
  for (const p of r.picks) {
    const note = p.missing && p.missing.length ? ' _(non misurato: ' + p.missing.join(', ') + ')_' : '';
    L.push('| ' + p.slot + ' | ' + p.name + ' | ' + p.cli + ' | $' + p.price + ' | ' + p.why + note + ' |');
  }
  if (r.pool_warning) { L.push(''); L.push('> Attenzione: ' + r.pool_warning); }
  L.push('');
}
L.push('<!-- model-routing-governor:end -->');
return [{ json: Object.assign({}, d, { block: L.join('\n') }) }];

// Innesta il blocco e allega l'hash letto: la scrittura e transazionale,
// quindi una modifica concorrente la fa fallire invece di sovrascriverla.
const d = $('Render CRM block').first().json;
const crm = $input.first().json;
const raw = (crm.content && crm.content[0] && crm.content[0].text) || crm;
const payload = typeof raw === 'string' ? JSON.parse(raw) : raw;
const content = String(payload.full_content || payload.content || '');
const hash = payload.content_hash;
if (!content) throw new Error('Lettura del CRM senza contenuto');
if (!hash) throw new Error('Lettura del CRM senza content_hash: la scrittura non sarebbe transazionale');
const BEGIN = '<!-- model-routing-governor:start -->';
const END = '<!-- model-routing-governor:end -->';
const i = content.indexOf(BEGIN); const j = content.indexOf(END);
if (i < 0 || j < 0) throw new Error('Delimitatori del blocco governato assenti nel CRM');
// Se l'impronta del catalogo non cambia non si riscrive: evita una scrittura
// a settimana che dice sempre la stessa cosa.
const prev = content.match(/<!-- model-routing-governor:input=([0-9a-f]+) -->/);
if (prev && prev[1] === d.fingerprint) return [];
const updated = content.slice(0, i) + d.block + content.slice(j + END.length);
return [{ json: { content: updated, expected_hash: hash, fingerprint: d.fingerprint, previous_fingerprint: prev ? prev[1] : null, catalog_count: d.catalog.length, assigned: d.routing.filter(r => !r.unassigned).length, unassigned: d.routing.filter(r => r.unassigned).map(r => r.role.id) } }];
